#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double T;
    int N;
    cin >> T >> N;

    vector<double> x(N);
    for (double &v : x) cin >> v;
    sort(x.begin(), x.end());

    double smallest = min(x[0] + (x[1] - x[0]) / 2.0,
                          T - x[N - 1] + (x[N - 1] - x[N - 2]) / 2.0);

    for (int i = 1; i + 1 < N; ++i) {
        double length = (x[i] - x[i - 1]) / 2.0 +
                        (x[i + 1] - x[i]) / 2.0;
        smallest = min(smallest, length);
    }

    cout << fixed << setprecision(2) << smallest << '\n';
    return 0;
}
